import{_ as p,a0 as r,w as o,s as d,ao as l,I as a,x as n,a1 as i,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"Linux 系統開機啓動項清理 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 系統開機啓動項清理 | LCTT (201709) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 系統開機啓動項清理 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 系統開機啓動項清理 | LCTT (201709) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201709/20160518 Cleaning Up Your Linux Startup Process","title":"Linux 系統開機啓動項清理","tag":"201709","desc":""},"relativePath":"201709/20160518 Cleaning Up Your Linux Startup Process.md","filePath":"[post].md"}'),u={name:"201709/20160518 Cleaning Up Your Linux Startup Process.md"};function c(g,s,h,b,m,k){const e=r("Link");return o(),d("div",null,[s[17]||(s[17]=l(`<h1 id="linux-系統開機啓動項清理" tabindex="-1">Linux 系統開機啓動項清理 <a class="header-anchor" href="#linux-系統開機啓動項清理" aria-label="Permalink to “Linux 系統開機啓動項清理”">​</a></h1><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/banner-cleanup-startup.png?itok=dCcKwdoP" alt="Linux cleanup" title="Clean up your startup process"></p><p>一般情況下，常規用途的 Linux 發行版在開機啓動時拉起各種相關服務進程，包括許多你可能無需使用的服務，例如<ruby>藍牙<rt>bluetooth</rt></ruby>、Avahi、 <ruby>調製解調管理器<rt>ModemManager</rt></ruby>、ppp-dns（LCTT 譯註：此處作者筆誤 ppp-dns 應該為 pppd-dns) 等服務進程，這些都是什麼東西？用於哪裏，有何功能？</p><p>Systemd 提供了許多很好的工具用於查看系統啓動情況，也可以控制在系統啓動時運行什麼。在這篇文章中，我將説明在 Systemd 類發行版中如何關閉一些令人討厭的進程。</p><h3 id="查看開機啓動項" tabindex="-1">查看開機啓動項 <a class="header-anchor" href="#查看開機啓動項" aria-label="Permalink to “查看開機啓動項”">​</a></h3><p>在過去，你能很容易通過查看 <code>/etc/init.d</code> 瞭解到哪些服務進程會在引導時啓動。Systemd 以不同的方式展現，你可以使用如下命令羅列允許開機啓動的服務進程。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ systemctl list-unit-files --type=service | grep enabled</span></span>
<span class="line"><span>accounts-daemon.service                    enabled</span></span>
<span class="line"><span>anacron-resume.service                     enabled</span></span>
<span class="line"><span>anacron.service                            enabled</span></span>
<span class="line"><span>bluetooth.service                          enabled</span></span>
<span class="line"><span>brltty.service                             enabled</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>在此列表頂部，對我來説，藍牙服務是冗餘項，因為在該電腦上我不需要使用藍牙功能，故無需運行此服務。下面的命令將停止該服務進程，並且使其開機不啓動。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl stop bluetooth.service</span></span>
<span class="line"><span>$ sudo systemctl disable bluetooth.service</span></span></code></pre></div><p>你可以通過下面命令確定是否操作成功。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ systemctl status bluetooth.service</span></span>
<span class="line"><span> bluetooth.service - Bluetooth service</span></span>
<span class="line"><span>  Loaded: loaded (/lib/systemd/system/bluetooth.service; disabled; vendor preset: enabled)</span></span>
<span class="line"><span>  Active: inactive (dead)</span></span>
<span class="line"><span>    Docs: man:bluetoothd(8)</span></span></code></pre></div><p>停用的服務進程仍然能夠被另外一個服務進程啓動。如果你真的想在任何情況下系統啓動時都不啓動該進程，無需卸載該它，只需要把它掩蓋起來就可以阻止該進程在任何情況下開機啓動。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl mask bluetooth.service</span></span>
<span class="line"><span> Created symlink from /etc/systemd/system/bluetooth.service to /dev/null.</span></span></code></pre></div><p>一旦你對禁用該進程啓動而沒有出現負面作用感到滿意，你也可以選擇卸載該程序。</p><p>通過執行命令可以獲得如下服務列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ systemctl list-unit-files --type=service                       </span></span>
<span class="line"><span>UNIT FILE                                  STATE   </span></span>
<span class="line"><span>accounts-daemon.service                    enabled</span></span>
<span class="line"><span>acpid.service                              disabled</span></span>
<span class="line"><span>alsa-restore.service                       static    </span></span>
<span class="line"><span>alsa-utils.service                         masked</span></span></code></pre></div><p>你不能啓用或禁用靜態服務，因為靜態服務被其他的進程所依賴，並不意味着它們自己運行。</p><h3 id="哪些服務能夠禁止" tabindex="-1">哪些服務能夠禁止？ <a class="header-anchor" href="#哪些服務能夠禁止" aria-label="Permalink to “哪些服務能夠禁止？”">​</a></h3><p>如何知道你需要哪些服務，而哪些又是可以安全地禁用的呢？它總是依賴於你的個性化需求。</p><p>這裏舉例了幾個服務進程的作用。許多服務進程都是發行版特定的，所以你應該看看你的發行版文檔（比如通過 google 或 StackOverflow）。</p>`,20)),a("ul",null,[s[4]||(s[4]=l("<li><strong>accounts-daemon.service</strong> 是一個潛在的安全風險。它是 AccountsService 的一部分，AccountsService 允許程序獲得或操作用户賬户信息。我不認為有好的理由能使我允許這樣的後台操作，所以我選擇<ruby>掩蓋<rt>mask</rt></ruby>該服務進程。</li><li><strong>avahi-daemon.service</strong> 用於零配置網絡發現，使電腦超容易發現網絡中打印機或其他的主機，我總是禁用它，別漏掉它。</li><li><strong>brltty.service</strong> 提供布萊葉盲文設備支持，例如布萊葉盲文顯示器。</li><li><strong>debug-shell.service</strong> 開放了一個巨大的安全漏洞（該服務提供了一個無密碼的 root shell ，用於幫助 調試 systemd 問題），除非你正在使用該服務，否則永遠不要啓動服務。</li><li><strong>ModemManager.service</strong> 該服務是一個被 dbus 激活的守護進程，用於提供移動<ruby>寬頻<rt>broadband</rt></ruby>（2G/3G/4G）接口，如果你沒有該接口，無論是內置接口，還是通過如藍牙配對的電話，以及 USB 適配器，那麼你也無需該服務。</li><li><strong>pppd-dns.service</strong> 是一個計算機發展的遺物，如果你使用撥號接入互聯網的話，保留它，否則你不需要它。</li><li><strong>rtkit-daemon.service</strong> 聽起來很可怕，聽起來像是 rootkit。 但是你需要該服務，因為它是一個<ruby>實時內核調度器<rt>real-time kernel scheduler</rt></ruby>。</li>",7)),a("li",null,[s[1]||(s[1]=a("strong",null,"whoopsie.service",-1)),s[2]||(s[2]=n(" 是 Ubuntu 錯誤報告服務。它用於收集 Ubuntu 系統崩潰報告，併發送報告到 ",-1)),i(e,{href:"https://daisy.ubuntu.com"},{default:t(()=>[...s[0]||(s[0]=[n("https://daisy.ubuntu.com",-1)])]),_:1}),s[3]||(s[3]=n(" 。 你可以放心地禁止其啓動，或者永久的卸載它。",-1))]),s[5]||(s[5]=a("li",null,[a("strong",null,"wpa_supplicant.service"),n(" 僅在你使用 Wi-Fi 連接時需要。")],-1))]),s[18]||(s[18]=l(`<h3 id="系統啓動時發生了什麼" tabindex="-1">系統啓動時發生了什麼？ <a class="header-anchor" href="#系統啓動時發生了什麼" aria-label="Permalink to “系統啓動時發生了什麼？”">​</a></h3><p>Systemd 提供了一些命令幫助調試系統開機啓動問題。該命令會重演你的系統啓動的所有消息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ journalctl -b</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- Logs begin at Mon 2016-05-09 06:18:11 PDT,</span></span>
<span class="line"><span>end at Mon 2016-05-09 10:17:01 PDT. --</span></span>
<span class="line"><span>May 16 06:18:11 studio systemd-journal[289]:</span></span>
<span class="line"><span>Runtime journal (/run/log/journal/) is currently using 8.0M.</span></span>
<span class="line"><span>Maximum allowed usage is set to 157.2M.</span></span>
<span class="line"><span>Leaving at least 235.9M free (of currently available 1.5G of space).</span></span>
<span class="line"><span>Enforced usage limit is thus 157.2M.</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>通過命令 <code>journalctl -b -1</code> 可以複審前一次啓動，<code>journalctl -b -2</code> 可以複審倒數第 2 次啓動，以此類推。</p><p>該命令會打印出大量的信息，你可能並不關注所有信息，只是關注其中問題相關部分。為此，系統提供了幾個過濾器，用於幫助你鎖定目標。讓我們以進程號為 1 的進程為例，該進程是所有其它進程的父進程。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ journalctl _PID=1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>May 08 06:18:17 studio systemd[1]: Starting LSB: Raise network interfaces....</span></span>
<span class="line"><span>May 08 06:18:17 studio systemd[1]: Started LSB: Raise network interfaces..</span></span>
<span class="line"><span>May 08 06:18:17 studio systemd[1]: Reached target System Initialization.</span></span>
<span class="line"><span>May 08 06:18:17 studio systemd[1]: Started CUPS Scheduler.</span></span>
<span class="line"><span>May 08 06:18:17 studio systemd[1]: Listening on D-Bus System Message Bus Socket</span></span>
<span class="line"><span>May 08 06:18:17 studio systemd[1]: Listening on CUPS Scheduler.</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>這些打印消息顯示了什麼被啓動，或者是正在嘗試啓動。</p><p>一個最有用的命令工具之一 <code>systemd-analyze blame</code>，用於幫助查看哪個服務進程啓動耗時最長。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ systemd-analyze blame</span></span>
<span class="line"><span>         8.708s gpu-manager.service</span></span>
<span class="line"><span>         8.002s NetworkManager-wait-online.service</span></span>
<span class="line"><span>         5.791s mysql.service</span></span>
<span class="line"><span>         2.975s dev-sda3.device</span></span>
<span class="line"><span>         1.810s alsa-restore.service</span></span>
<span class="line"><span>         1.806s systemd-logind.service</span></span>
<span class="line"><span>         1.803s irqbalance.service</span></span>
<span class="line"><span>         1.800s lm-sensors.service</span></span>
<span class="line"><span>         1.800s grub-common.service</span></span></code></pre></div><p>這個特定的例子沒有出現任何異常，但是如果存在系統啓動瓶頸，則該命令將能發現它。</p><p>你也能通過如下資源瞭解 Systemd 如何工作：</p>`,11)),a("ul",null,[a("li",null,[i(e,{href:"https://www.linux.com/learn/understanding-and-using-systemd"},{default:t(()=>[...s[6]||(s[6]=[n("理解和使用 Systemd",-1)])]),_:1})]),a("li",null,[i(e,{href:"https://www.linux.com/learn/intro-systemd-runlevels-and-service-management-commands"},{default:t(()=>[...s[7]||(s[7]=[n("介紹 Systemd 運行級別和服務管理命令",-1)])]),_:1})]),a("li",null,[i(e,{href:"https://www.linux.com/learn/here-we-go-again-another-linux-init-intro-systemd"},{default:t(()=>[...s[8]||(s[8]=[n("再次前行，另一個 Linux 初始化系統：Systemd 介紹",-1)])]),_:1})])]),s[19]||(s[19]=a("hr",null,null,-1)),a("p",null,[s[10]||(s[10]=n("via: ",-1)),i(e,{href:"https://www.linux.com/learn/cleaning-your-linux-startup-process"},{default:t(()=>[...s[9]||(s[9]=[n("https://www.linux.com/learn/cleaning-your-linux-startup-process",-1)])]),_:1})]),a("p",null,[s[14]||(s[14]=n("作者：",-1)),i(e,{href:"https://www.linux.com/users/cschroder"},{default:t(()=>[...s[11]||(s[11]=[n("David Both",-1)])]),_:1}),s[15]||(s[15]=n(" 譯者：",-1)),i(e,{href:"https://github.com/penghuster"},{default:t(()=>[...s[12]||(s[12]=[n("penghuster",-1)])]),_:1}),s[16]||(s[16]=n(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[13]||(s[13]=[n("wxy",-1)])]),_:1})]),s[20]||(s[20]=a("p",null,"本文由 LCTT 原創編譯，Linux中國 榮譽推出",-1))])}const x=p(u,[["render",c]]);export{f as __pageData,x as default};
